/* Шаг батута для «Читать в кавычках»: значение либо отскок к соседу по рекурсии. */
static fl_status kompilyator_flang_chitat_v_kavychkah_step(fl_ctx *ctx, const fl_value *args, fl_bounce *bounce, fl_value *result,
                                                           fl_error *error) {
  fl_value simvoly = args[0]; /* «символы» */
  fl_value zakryvayuschaya = args[1]; /* «закрывающая» */
  fl_value nakopleno = args[2]; /* «накоплено» */
  fl_value sedeno = args[3]; /* «съедено» */
  for (;;) {
    FL_TRY(fl_tick(ctx, "Читать в кавычках", error));
    if (fl_chain_empty(simvoly)) {
      fl_value fl_t174[5];
      fl_t174[0] = nakopleno; /* «значение» */
      fl_t174[1] = sedeno; /* «съедено» */
      fl_t174[2] = fl_flag(false); /* «закрыто» */
      fl_t174[3] = fl_flag(false); /* «сломано» */
      fl_t174[4] = fl_flag(false); /* «съело перевод» */
      fl_value fl_t173 = fl_nothing();
      FL_TRY(fl_record_new(ctx, kompilyator_flang_names_5, fl_t174, 5, &fl_t173, error));
      *result = fl_t173;
      return FL_OK;
    } else if (fl_chain_cons(simvoly)) {
      const fl_value golova = fl_chain_head(simvoly); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(simvoly); /* хвост «хвост» */
      bool fl_t175 = false;
      FL_TRY(fl_cond(ctx, fl_flag(fl_equal(golova, zakryvayuschaya)), &fl_t175, error));
      if (fl_t175) {
        fl_value fl_t176 = fl_nothing();
        FL_TRY(fl_add(ctx, sedeno, fl_number(1.0), &fl_t176, error));
        fl_value fl_t178[5];
        fl_t178[0] = nakopleno; /* «значение» */
        fl_t178[1] = fl_t176; /* «съедено» */
        fl_t178[2] = fl_flag(true); /* «закрыто» */
        fl_t178[3] = fl_flag(false); /* «сломано» */
        fl_t178[4] = fl_flag(false); /* «съело перевод» */
        fl_value fl_t177 = fl_nothing();
        FL_TRY(fl_record_new(ctx, kompilyator_flang_names_5, fl_t178, 5, &fl_t177, error));
        *result = fl_t177;
        return FL_OK;
      } else {
        bool fl_t179 = false;
        FL_TRY(fl_cond(ctx, fl_flag(fl_equal(golova, kompilyator_flang_text_205)), &fl_t179, error));
        if (fl_t179) {
          fl_value fl_t180 = fl_nothing();
          FL_TRY(fl_add(ctx, sedeno, fl_number(1.0), &fl_t180, error));
          /* хвостовой вызов «Читать экранированное» — отскок, а не кадр стека */
          bounce->args[0] = hvost;
          bounce->args[1] = zakryvayuschaya;
          bounce->args[2] = nakopleno;
          bounce->args[3] = fl_t180;
          bounce->next = kompilyator_flang_chitat_ekranirovannoe_step;
          return FL_OK;
        } else {
          fl_value fl_t181 = fl_nothing();
          FL_TRY(fl_concat(ctx, nakopleno, golova, &fl_t181, error));
          fl_value fl_t182 = fl_nothing();
          FL_TRY(fl_add(ctx, sedeno, fl_number(1.0), &fl_t182, error));
          const fl_value fl_t183 = zakryvayuschaya;
          simvoly = hvost;
          zakryvayuschaya = fl_t183;
          nakopleno = fl_t181;
          sedeno = fl_t182;
          continue;
        }
      }
    } else {
      return fl_match_fail(ctx, simvoly, error);
    }
  }
}

/*
 * Функция flang «Читать в кавычках».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Взаимная хвостовая рекурсия с «Читать юникод», «Читать экранированное»: вызовы идут через батут.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param simvoly — «символы»: список: строка
 * @param zakryvayuschaya — «закрывающая»: строка
 * @param nakopleno — «накоплено»: строка
 * @param sedeno — «съедено»: число
 * @return значение: «Чтение»
 */
fl_status kompilyator_flang_chitat_v_kavychkah(fl_ctx *ctx, fl_value simvoly, fl_value zakryvayuschaya, fl_value nakopleno, fl_value sedeno, fl_value *result, fl_error *error) {
  fl_value args[4];
  args[0] = simvoly;
  args[1] = zakryvayuschaya;
  args[2] = nakopleno;
  args[3] = sedeno;
  FL_TRY(fl_enter(ctx, "Читать в кавычках", error));
  {
    const fl_status status = fl_trampoline(ctx, kompilyator_flang_chitat_v_kavychkah_step, args, 4, "Читать в кавычках",
                                           result, error);
    fl_leave(ctx);
    return status;
  }
}

