      const fl_value fl_t15071 = signatura;
      const fl_value fl_t15072 = gde;
      const fl_value fl_t15073 = tablicy;
      postusloviya = hvost;
      funkciya = fl_t15070;
      signatura = fl_t15071;
      gde = fl_t15072;
      tablicy = fl_t15073;
